230	fn discover_marketplace_paths_from_roots(
231	    additional_roots: &[AbsolutePathBuf],
232	    home_dir: Option<&Path>,
233	) -> Vec<AbsolutePathBuf> {
234	    let mut paths = Vec::new();
235	
236	    if let Some(home) = home_dir {
237	        let path = home.join(MARKETPLACE_RELATIVE_PATH);
238	        if path.is_file()
239	            && let Ok(path) = AbsolutePathBuf::try_from(path)
240	        {
241	            paths.push(path);
242	        }
243	    }
244	
245	    for root in additional_roots {
246	        if let Some(repo_root) = get_git_repo_root(root.as_path())
247	            && let Ok(repo_root) = AbsolutePathBuf::try_from(repo_root)
248	            && let Ok(path) = repo_root.join(MARKETPLACE_RELATIVE_PATH)
249	            && path.as_path().is_file()
250	            && !paths.contains(&path)
251	        {
252	            paths.push(path);
253	        }
254	    }
255	
256	    paths
257	}
