259	fn load_marketplace(path: &AbsolutePathBuf) -> Result<MarketplaceFile, MarketplaceError> {
260	    let contents = fs::read_to_string(path.as_path()).map_err(|err| {
261	        if err.kind() == io::ErrorKind::NotFound {
262	            MarketplaceError::MarketplaceNotFound {
263	                path: path.to_path_buf(),
264	            }
265	        } else {
266	            MarketplaceError::io("failed to read marketplace file", err)
267	        }
268	    })?;
269	    serde_json::from_str(&contents).map_err(|err| MarketplaceError::InvalidMarketplaceFile {
270	        path: path.to_path_buf(),
271	        message: err.to_string(),
272	    })
273	}
